function dateDb(mixed $value): ?string {$value=trim((string)$value);if($value==='')return null;if(preg_match('/^(\d{2})\/(\d{2})\/(\d{4})$/',$value,$m))return $m[3].'-'.$m[2].'-'.$m[1];if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$value))return $value;return null;}
function periodCalendarDays(array $employee,string $period): int {$startDay=1;$endDay=30;if(!empty($employee['hire_date'])&&substr((string)$employee['hire_date'],0,7)===$period)$startDay=(int)substr((string)$employee['hire_date'],8,2);if(!empty($employee['termination_date'])&&substr((string)$employee['termination_date'],0,7)===$period)$endDay=(int)substr((string)$employee['termination_date'],8,2);return max(0,min(30,$endDay-$startDay+1));}
