function recalculatePeriod(int $periodId, string $period, int $companyId): void {global $pdo;$s=$pdo->prepare('SELECT pv.values_json FROM payroll_periods pp JOIN parameter_versions pv ON pv.company_id=pp.company_id AND pv.period=pp.period WHERE pp.id=? AND pp.company_id=?');$s->execute([$periodId,$companyId]);$p=json_decode((string)$s->fetchColumn(),true)?:[];$es=$pdo->prepare('SELECT e.*,COALESCE(v.medical_leave_days,0) medical_leave_days,COALESCE(v.unpaid_leave_days,0) unpaid_leave_days,COALESCE(v.overtime_50,0) overtime_50,COALESCE(v.overtime_100,0) overtime_100,COALESCE(v.taxable_bonus,0) taxable_bonus,COALESCE(v.commissions,0) commissions,COALESCE(v.guaranteed_gratification,0) guaranteed_gratification,COALESCE(v.non_taxable_bonus,0) non_taxable_bonus,COALESCE(v.advance,0) advance,COALESCE(v.company_loan,0) company_loan,COALESCE(v.ccaf_loan,0) ccaf_loan,COALESCE(v.other_discounts,0) other_discounts FROM employees e LEFT JOIN payroll_variables v ON v.employee_id=e.id AND v.period_id=? WHERE e.company_id=? AND (e.status="Activo" OR e.termination_date IS NOT NULL) AND (e.hire_date IS NULL OR e.hire_date<=LAST_DAY(?)) AND (e.termination_date IS NULL OR e.termination_date>=?)');$es->execute([$periodId,$companyId,$period.'-01',$period.'-01']);$calc=new PayrollCalculator();$save=$pdo->prepare('INSERT INTO payslips(period_id,employee_id,calculation_json) VALUES(?,?,?) ON DUPLICATE KEY UPDATE calculation_json=VALUES(calculation_json)');foreach($es as $e){$v=[];foreach(['medical_leave_days','unpaid_leave_days','overtime_50','overtime_100','taxable_bonus','commissions','guaranteed_gratification','non_taxable_bonus','advance','company_loan','ccaf_loan','other_discounts'] as $key)$v[$key]=$e[$key];$v['calendar_days']=periodCalendarDays($e,$period);$save->execute([$periodId,$e['id'],json_encode($calc->calculate($e,$v,$p))]);}}
