if($user && $_SERVER['REQUEST_METHOD']==='POST' && $page==='employee-csv-import'){ $required=['rut','nombre completo','fecha ingreso','fecha término','cargo','sueldo base','tipo contrato','tipo gratificación','institución salud','plan isapre uf','afp','colación','movilización','cargas familiares','ccaf','comuna','región','tasa mutual','cotiza afp','estado'];try{if(empty($_FILES['worker_csv']['tmp_name']))throw new RuntimeException('Selecciona un archivo CSV.');$fp=fopen($_FILES['worker_csv']['tmp_name'],'rb');if(!$fp)throw new RuntimeException('No fue posible leer el archivo CSV.');$header=fgetcsv($fp,0,';');if(!$header)throw new RuntimeException('El CSV está vacío.');$header=array_map(fn($v)=>strtolower(trim(preg_replace('/^\xEF\xBB\xBF/','',(string)$v))),$header);$map=[];foreach($required as $key){$pos=array_search($key,$header,true);if($pos===false)throw new RuntimeException('Falta la columna "'.$key.'" en el CSV.');$map[$key]=$pos;}$sql='INSERT INTO employees(company_id,rut,full_name,hire_date,termination_date,position,base_salary,contract_type,gratification_type,health_institution,isapre_plan_uf,afp,meal_allowance,transport_allowance,family_loads,ccaf,commune,region,mutual_rate,contributes_afp,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),hire_date=VALUES(hire_date),termination_date=VALUES(termination_date),position=VALUES(position),base_salary=VALUES(base_salary),contract_type=VALUES(contract_type),gratification_type=VALUES(gratification_type),health_institution=VALUES(health_institution),isapre_plan_uf=VALUES(isapre_plan_uf),afp=VALUES(afp),meal_allowance=VALUES(meal_allowance),transport_allowance=VALUES(transport_allowance),family_loads=VALUES(family_loads),ccaf=VALUES(ccaf),commune=VALUES(commune),region=VALUES(region),mutual_rate=VALUES(mutual_rate),contributes_afp=VALUES(contributes_afp),status=VALUES(status)';$save=$pdo->prepare($sql);$count=0;while(($row=fgetcsv($fp,0,';'))!==false){$values