if($user && $page==='payslip'){ $period=$_GET['period']??'';$eid=(int)($_GET['employee']??0);$s=$pdo->prepare('SELECT e.full_name,e.rut,e.position,e.contract_type,e.health_institution,e.afp,pp.period,p.calculation_json FROM employees e JOIN payslips p ON p.employee_id=e.id JOIN payroll_periods pp ON pp.id=p.period_id WHERE e.company_id=? AND e.id=? AND pp.period=?');$s->execute([$user['company_id'],$eid,$period]);$x=$s->fetch();if(!$x)go('periods');$r=json_decode($x['calculation_json'],true);$money=fn($v)=>'$'.number_format((float)$v,0,',','.');$body='<article class="payslip"><header><h1>LIQUIDACIÓN DE SUELDO</h1><p>Período: '.h($x['period']).'</p></header><section class="employee-data"><b>RUT:</b> '.h($x['rut']).' &nbsp; <b>Nombre:</b> '.h($x['full_name']).'<br><b>Cargo:</b> '.h($x['position']).' &nbsp; <b>Contrato:</b> '.h($x['contract_type']).'<br><b>AFP:</b> '.h($x['afp']).' &nbsp; <b>Salud:</b> '.h($x['health_institution']).'</section><div class="payslip-columns"><section><h2>Haberes</h2><p>Sueldo base proporcional <strong>'.$money($r['sb']).'</strong></p><p>Horas extra 50% <strong>'.$money($r['ot50']).'</strong></p><p>Horas extra 100% <strong>'.$money($r['ot100']).'</strong></p><p>Bono imponible <strong>'.$money($r['bonus']).'</strong></p><p>Comisiones <strong>'.$money($r['comm']).'</strong></p><p>Gratificación <strong>'.$money($r['grat']).'</strong></p><hr><p>Total haberes <strong>'.$money($r['haberes']).'</strong></p></section><section><h2>Descuentos</h2><p>AFP <strong>'.$money($r['afp']).'</strong></p><p>Salud <strong>'.$money($r['health']).'</strong></p><p>Seguro cesantía <strong>'.$money($r['scWorker']).'</strong></p><p>Impuesto único <strong>'.$money($r['iusc']).'</strong></p><hr><p>Total descuentos <strong>'.$money($r['discounts']).'</strong></p></section></div><div class="net-pay">LÍQUIDO A PAGAR: '.$money($r['net']).'</div><button onclick="window.print()">Imprimir / Guardar PDF</button></article>';layout('Liquidación',$body);exit; }
if($user && $page==='guide'){layout('Guía LRE','<section class="card"><h1>Guía del Libro de Remuneraciones</h1><p>1. Cierra las variables y calcula el período completo.</p><p>2. Revisa el resumen y las liquidaciones individuales.</p><p>3. Descarga el archivo LRE desde el enlace del período. Se genera delimitado por punto y coma.</p><p>4. Carga el archivo en Mi DT usando el modelo oficial correspondiente al mes. La aplicación no reemplaza la autenticación ni el envío en Mi DT.</p><p>5. Conserva el CSV y la liquidación cerrada como respaldo.</p></section>');exit; }
function periodPicker(): string {global $pdo,$user,$page;if(!$user)return ''; $s=$pdo->prepare('SELECT period FROM payroll_periods WHERE company_id=? ORDER BY period DESC');$s->execute([$user['company_id']]);$periods=$s->fetchAll(PDO::FETCH_COLUMN);if(!$periods)return ''; $current=$_GET['period']??$periods[0];$periodPages=['variables-grid','variables','calculate','payslips','summary','book','lre','payslip','parameters-edit','parameter-advanced'];$target=in_array($page,$periodPages,true)?$page:'variables-grid';$options='';foreach($periods as $period)$options.='<option value="'.h($period).'"'.($period===$current?' selected':'').'>'.h($period).'</option>';return '<form class="period-picker" method="get" action="index.php"><input type="hidden" name="page" value="'.h($target).'"><label for="active-period">Período</label><select id="active-period" name="period" onchange="this.form.submit()">'.$options.'</select></form>'; }
function dateFormatScript(): string {return '<script>document.querySelectorAll(".employee-grid input[type=date]").forEach(function(input){input.setAttribute("lang","es-CL");});</script>'; }
function sheetNavigation(): string { global $user,$page; if(!$user)return ''; $period=$_GET['period']??'';$items=[['01_Parametros_Previred','parameters'],['02_BD_Trabajadores','employees'],['03_Variables_y_Calculos','periods&sheet=variables-grid'],['04_Liquidacion_Formato','periods&sheet=payslips'],['05_Resumen_Cotizaciones','periods&sheet=summary'],['06_Libro_Remuneraciones','periods&sheet=book'],['07_Guia_LRE','guide'],['08_Crear_Empresa','company-new']];$html='<nav class="sheet-nav" aria-label="Hojas del libro">';foreach($items as $item){$base=explode('&',$item[1])[0];$active=$page===$base?' active':'';$url='?page='.$item[1].($period?'&period='.rawurlencode($period):'');$html.='<a href="'.$url.'" class="sheet-tab'.$active.'">'.h($item[0]).'</a>';}return $html.'</nav>'; }
function layout(string $title, string $body): void {global $user,$page;$readOnlyScript=($user&&($user['role']??'')!=='admin'&&in_array($page,['parameters-edit','parameter-advanced'],true))?'<script>document.querySelectorAll("input,select,textarea,button").forEach(function(el){el.disabled=true;});</script>':'';echo '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).' · Remuneraciones</title><link rel="stylesheet" href="style.css"></head><body class="page-'.h($page).'">'.($user?'<header class="app-header"><strong>Remuneraciones</strong><span>'.h($title).'</span>'.companyPicker().periodPicker().'<a href="?page=profile">Mi perfil</a><a href="?page=company-new">Nueva empresa</a>'.(($user['role']??'')==='admin'?'<a href="?page=users">Usuarios</a>':'').(($user['global_role']??'none')==='admin'?'<a href="?page=global-users">Solicitudes</a>':'').'<a href="?page=logout">Salir</a></header>':'').'<main>'.$body.'</main>'.sheetNavigation().dateFormatScript().$readOnlyScript.'</body></html>';}
