function activeCompanyName(): string {global $pdo,$user;$s=$pdo->prepare('SELECT name FROM companies WHERE id=?');$s->execute([(int)($user['company_id']??0)]);return (string)($s->fetchColumn()?:'');}
function numberToWordsEs(int $number): string {$units=['cero','uno','dos','tres','cuatro','cinco','seis','siete','ocho','nueve','diez','once','doce','trece','catorce','quince','dieciséis','diecisiete','dieciocho','diecinueve','veinte'];$tens=['','','veinte','treinta','cuarenta','cincuenta','sesenta','setenta','ochenta','noventa'];$hundreds=['','ciento','doscientos','trescientos','cuatrocientos','quinientos','seiscientos','setecientos','ochocientos','novecientos'];if($number<21)return $units[$number];if($number<100){$t=$tens[intdiv($number,10)];return $number%10?$t.' y '.$units[$number%10]:$t;}if($number<1000){if($number===100)return 'cien';return $hundreds[intdiv($number,100)].($number%100?' '.numberToWordsEs($number%100):'');}if($number<1000000){$th=intdiv($number,1000);$rest=$number%1000;$prefix=$th===1?'mil':numberToWordsEs($th).' mil';return $prefix.($rest?' '.numberToWordsEs($rest):'');}if($number<1000000000){$mill=intdiv($number,1000000);$rest=$number%1000000;$prefix=$mill===1?'un millón':numberToWordsEs($mill).' millones';return $prefix.($rest?' '.numberToWordsEs($rest):'');}return (string)$number;}
function moneyWords(float $value): string {$value=max(0,round($value));return ucfirst(numberToWordsEs((int)$value)).' pesos';}
function payslipHtml(array $x,array $r,string $period,string $companyName): string {$money=fn($v)=>'$'.number_format((float)$v,0,',','.');$totalLegal=(float)$r['afp']+(float)$r['health']+(float)$r['scWorker']+(float)$r['iusc'];$other=(float)($r['advance']??0)+(float)($r['company_loan']??0)+(float)($r['ccaf_loan']??0)+(float)($r['other_discounts']??0);$nonTax=(float)$r['haberes']-(float)$r['taxable'];$hire=!empty($x['hire_date'])?date('d/m/Y',strtotime((string)$x['hire_date'])):'';return '<article class="payslip payslip-reference"><header class="payslip-company"><div><h1>LIQUIDACIÓN DE SUELDO</h1><p><strong>'.h($companyName).'</strong></p><p>Período liquidado: '.h($period).'</p></div><div class="payslip-date"><b>Fecha:</b> '.date('d/m/Y').'<br><b>Alcance liquidado:</b> '.h($period).'</div></header><section class="employee-data"><div><b>RUT:</b> '.h($x['rut']).'</div><div><b>Nombre:</b> '.h($x['full_name']).'</div><div><b>Cargo:</b> '.h($x['position']).'</div><div><b>Fecha ingreso:</b> '.h($hire).'</div><div><b>Contrato:</b> '.h($x['contract_type']).'</div><div><b>AFP:</b> '.h($x['afp']).' &nbsp; <b>Salud:</b> '.h($x['health_institution']).'</div></section><div class="payslip-summary-grid"><section><h2>Haberes</h2>'.payslipRow('Sueldo base proporcional',$r['sb'],$money).''.payslipRow('Horas extra 50%',$r['ot50'],$money).''.payslipRow('Horas extra 100%',$r['ot100'],$money).''.payslipRow('Bono imponible',$r['bonus'],$money).''.payslipRow('Comisiones',$r['comm'],$money).''.payslipRow('Gratificación',$r['grat'],$money).''.payslipTotalRow('Total imponible',$r['taxable'],$money).''.payslipRow('Colación',$r['meal'],$money).''.payslipRow('Movilización',$r['transport'],$money).''.payslipRow('Asignación familiar',$r['family'],$money).''.payslipRow('Aguinaldo no imponible',$r['nonTax'],$money).''.payslipTotalRow('Total no imponible',$nonTax,$money).''.payslipTotalRow('TOTAL HABERES',$r['haberes'],$money).'</section><section><h2>Descuentos</h2>'.payslipRow('AFP',$r['afp'],$money).''.payslipRow('Salud',$r['health'],$money).''.payslipRow('Seguro cesantía',$r['scWorker'],$money).''.payslipRow('Impuesto único',$r['iusc'],$money).''.payslipTotalRow('Total descuentos legales',$totalLegal,$money).''.payslipRow('Anticipo',$r['advance']??0,$money).''.payslipRow('Préstamo empresa',$r['company_loan']??0,$money).''.payslipRow('Préstamo CCAF',$r['ccaf_loan']??0,$money).''.payslipRow('Otros descuentos',$r['other_discounts']??0,$money).''.payslipTotalRow('Total otros descuentos',$other,$money).''.payslipTotalRow('TOTAL DESCUENTOS',$r['discounts'],$money).'</section></div><div class="net-pay payslip-net">LÍQUIDO A PAGAR: '.$money($r['net']).'</div><p class="amount-words"><b>SON:</b> '.h(moneyWords((float)$r['net'])).'</p><div class="receipt">Recibí conforme el monto indicado en esta liquidación, declarando haber recibido los haberes y descuentos señalados.</div><div class="signature-grid"><div><span></span><b>Firma del empleador</b><small>'.h($companyName).'</small></div><div><span></span><b>Firma del trabajador</b><small>'.h($x['full_name']).'</small></div></div></article>';}
