function payslipRow(string $label,mixed $value,callable $money): string {if(abs((float)$value)<0.00001)return '';return '<p>'.h($label).' <strong>'.$money($value).'</strong></p>';}
function payslipTotalRow(string $label,mixed $value,callable $money): string {return '<p class="total-line">'.h($label).' <strong>'.$money($value).'</strong></p>';}
